using Astrea.BattleActions;
using UnityEngine;
using UnityEngine.Localization.SmartFormat;

namespace Astrea;

[CreateAssetMenu(fileName = "DevotionOrbStarAbility", menuName = "Data/Battle/Effects/Orion/DevotionOrb Star Ability")]
public class DevotionOrbStarAbility : ActivateStarAbility
{
	[Header("Devotion Orb")]
	[SerializeField]
	private Effect vowReinforcementEffect;

	[SerializeField]
	private Effect protectiveSacramentEffect;

	[SerializeField]
	private Effect brightfulDecreeEffect;

	[SerializeField]
	private OmenLogic playerOmenLogic;

	[SerializeField]
	private OmenLogic allEnemiesOmenLogic;

	[Header("Description")]
	[SerializeField]
	private BattleAction randomTargetLightShieldAction;

	[SerializeField]
	private BattleAction playerSelfLightShieldAction;

	[SerializeField]
	private BattleAction areaEnemyLightShieldAction;

	private UnitEffects unitEffects => ReferenceSingleton<BattleHandler>.Instance.PlayerGameObject.GetComponent<UnitEffects>();

	public override string GetLocalizedDescription()
	{
		string text = "";
		if (GameScenesUtils.IsBattleScene())
		{
			int num = unitEffects.IsEffectActiveGetAmount(protectiveSacramentEffect);
			int num2 = unitEffects.IsEffectActiveGetAmount(brightfulDecreeEffect);
			if (num <= 0 || num2 <= 0)
			{
				text = ((num > 0) ? Smart.Format(playerSelfLightShieldAction.GetActionDescription(-3), GetDefensiveStarModifierText(num)) : ((num2 <= 0) ? GetDefaultLightShieldFinalDescription() : Smart.Format(areaEnemyLightShieldAction.GetActionDescription(-3), GetDefensiveStarModifierText(num2))));
			}
			else
			{
				string actionDescription = playerSelfLightShieldAction.GetActionDescription(-3);
				text = string.Concat(str2: Smart.Format(areaEnemyLightShieldAction.GetActionDescription(-3), GetDefensiveStarModifierText(num2)), str0: Smart.Format(actionDescription, GetDefensiveStarModifierText(num)), str1: "\n");
			}
		}
		else
		{
			text = GetDefaultLightShieldFinalDescription();
		}
		return Smart.Format(GetCastOrbLocalizedDescription(), text);
	}

	private string GetDefaultLightShieldFinalDescription()
	{
		return Smart.Format(randomTargetLightShieldAction.GetActionDescription(-3), GetDefensiveStarModifierText(0));
	}

	private string GetDefensiveStarModifierText(int targetModifierAmount)
	{
		if (GameScenesUtils.IsBattleScene())
		{
			int vowReinforcementEffectAmount = GetVowReinforcementEffectAmount(activateFeedback: false);
			if (vowReinforcementEffectAmount > 0 && targetModifierAmount > 0)
			{
				return actionValue + vowReinforcementEffectAmount + targetModifierAmount + $"({actionValue}+{vowReinforcementEffectAmount}+{targetModifierAmount})";
			}
			if (vowReinforcementEffectAmount > 0)
			{
				return actionValue + vowReinforcementEffectAmount + $"({actionValue}+{vowReinforcementEffectAmount})";
			}
			if (targetModifierAmount > 0)
			{
				return actionValue + targetModifierAmount + $"({actionValue}+{targetModifierAmount})";
			}
		}
		return actionValue.ToString();
	}

	public override void OnActivateStarAbility()
	{
		int num = unitEffects.IsEffectActiveGetAmountAndRemoveEffect(protectiveSacramentEffect);
		int num2 = unitEffects.IsEffectActiveGetAmountAndRemoveEffect(brightfulDecreeEffect);
		int modifiedActionValue = GetModifiedActionValue(num);
		int modifiedActionValue2 = GetModifiedActionValue(num2);
		if (num > 0 && num2 > 0)
		{
			PlaySFX();
			ReferenceSingleton<AssetsReference>.Instance.PlayerRunData.GoddessVerdictAmount += modifiedActionValue;
			ReferenceSingleton<AssetsReference>.Instance.PlayerRunData.GoddessVerdictAmount += modifiedActionValue2 * currentCorruptedAnimals.activeCorruptedAnimals.Count;
			playerOmenLogic.ActivateOmen(battleAction, modifiedActionValue, null, ReferenceSingleton<BattleHandler>.Instance.PlayerGameObject);
			allEnemiesOmenLogic.ActivateOmen(battleAction, modifiedActionValue2, null, ReferenceSingleton<BattleHandler>.Instance.PlayerGameObject);
		}
		else if (num > 0)
		{
			PlaySFX();
			ReferenceSingleton<AssetsReference>.Instance.PlayerRunData.GoddessVerdictAmount += modifiedActionValue;
			playerOmenLogic.ActivateOmen(battleAction, modifiedActionValue, null, ReferenceSingleton<BattleHandler>.Instance.PlayerGameObject);
		}
		else if (num2 > 0)
		{
			PlaySFX();
			ReferenceSingleton<AssetsReference>.Instance.PlayerRunData.GoddessVerdictAmount += modifiedActionValue2 * currentCorruptedAnimals.activeCorruptedAnimals.Count;
			allEnemiesOmenLogic.ActivateOmen(battleAction, modifiedActionValue2, null, ReferenceSingleton<BattleHandler>.Instance.PlayerGameObject);
		}
		else
		{
			ReferenceSingleton<AssetsReference>.Instance.PlayerRunData.GoddessVerdictAmount += GetModifiedActionValue();
			base.OnActivateStarAbility();
		}
	}

	protected override int GetModifiedActionValue()
	{
		int num = actionValue + GetVowReinforcementEffectAmount(activateFeedback: false);
		if (ReferenceSingleton<OrionOmensHandler>.Instance.PlatinumStarDevotionOmenAction != null)
		{
			num = ReferenceSingleton<OrionOmensHandler>.Instance.PlatinumStarDevotionOmenAction(num);
		}
		return num;
	}

	private int GetModifiedActionValue(int targetModifierAmount)
	{
		return GetModifiedActionValue() + targetModifierAmount;
	}

	private int GetVowReinforcementEffectAmount(bool activateFeedback)
	{
		return unitEffects.IsEffectActiveGetAmount(vowReinforcementEffect, activateFeedback);
	}
}
